    fun formatDate(millis: Long?, pattern: String): String =
        millis?.let { SimpleDateFormat(pattern, Locale.getDefault()).format(Date(it)) } ?: ""

    fun timer(views: RemoteViews, id: Int, target: Long?) {
        if (target == null) {
            views.setChronometer(id, SystemClock.elapsedRealtime(), null, false)
            return
        }
        val now = System.currentTimeMillis()
        views.setChronometer(id, SystemClock.elapsedRealtime() + (target - now), null, true)
        if (Build.VERSION.SDK_INT >= 24) views.setChronometerCountDown(id, target > now)
    }

    /** Styled text for `NWRichText`. Colors follow the theme at update time. */
    fun spans(context: Context, spans: List<FnwSpan>): CharSequence {
        val text = SpannableStringBuilder()
        for (span in spans) {
            val start = text.length
            text.append(span.text)
            val end = text.length
            if (start == end) continue
            val flags = Spanned.SPAN_EXCLUSIVE_EXCLUSIVE
            text.setSpan(AbsoluteSizeSpan(span.size.toInt(), true), start, end, flags)
            text.setSpan(ForegroundColorSpan(context.getColor(span.color)), start, end, flags)
            val style = when {
                span.bold && span.italic -> Typeface.BOLD_ITALIC
                span.bold -> Typeface.BOLD
                span.italic -> Typeface.ITALIC
                else -> null
            }
            style?.let { text.setSpan(StyleSpan(it), start, end, flags) }
            span.family?.let { text.setSpan(TypefaceSpan(it), start, end, flags) }
        }
        return text
    }

    fun progress(views: RemoteViews, id: Int, value: Double, max: Double) {
        val fraction = if (max <= 0.0) 0.0 else (value / max).coerceIn(0.0, 1.0)
        views.setProgressBar(id, 1000, (fraction * 1000).toInt(), false)
    }

    fun image(views: RemoteViews, id: Int, path: String) {
        val bitmap = if (path.isEmpty()) null else try {
            val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
            BitmapFactory.decodeFile(path, bounds)
            var sample = 1
            while (bounds.outWidth / sample > 800 || bounds.outHeight / sample > 800) sample *= 2
            BitmapFactory.decodeFile(path, BitmapFactory.Options().apply { inSampleSize = sample })
        } catch (e: Exception) {
            null
        }
        if (bitmap == null) {
            views.setViewVisibility(id, View.GONE)
        } else {
            views.setImageViewBitmap(id, bitmap)
            views.setViewVisibility(id, View.VISIBLE)
        }
    }

    /** Wakes [provider] up at [at] to redraw (timeline entries, timers). */
    fun schedule(context: Context, provider: Class<*>, at: Long?) {
        val alarms = context.getSystemService(Context.ALARM_SERVICE) as AlarmManager
        val intent = PendingIntent.getBroadcast(
            context, 1, Intent(context, provider).setAction(TICK), flags(),
        )
        if (at == null) {
            alarms.cancel(intent)
            return
        }
        if (Build.VERSION.SDK_INT >= 31 && !alarms.canScheduleExactAlarms()) {
            alarms.setAndAllowWhileIdle(AlarmManager.RTC, at, intent)
        } else {
            alarms.setExactAndAllowWhileIdle(AlarmManager.RTC, at, intent)
        }
    }
}

internal class FnwOption(
    val key: String,
    val label: String,
    val choices: Array<String>,
    val initial: String,
)

/** Provider class → widget name and its options. */
internal val FNW_OPTIONS = mapOf<String, Pair<String, List<FnwOption>>>(
    "com.example.app.fnw.WeatherWidgetProvider" to ("Weather" to listOf(
        FnwOption("city", "City", arrayOf("Cairo", "Giza"), "Cairo"),
    )),
)

/** Asks for each NWOption of a widget being placed or reconfigured. */
class FnwConfigureActivity : Activity() {
    private var widgetId = AppWidgetManager.INVALID_APPWIDGET_ID

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        widgetId = intent?.extras?.getInt(
            AppWidgetManager.EXTRA_APPWIDGET_ID, AppWidgetManager.INVALID_APPWIDGET_ID,
        ) ?: AppWidgetManager.INVALID_APPWIDGET_ID
        setResult(RESULT_CANCELED, Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID, widgetId))
        val provider = AppWidgetManager.getInstance(this).getAppWidgetInfo(widgetId)?.provider
        val spec = provider?.let { FNW_OPTIONS[it.className] }
        if (provider == null || spec == null) {
            finish()
            return
        }
        ask(provider, spec.first, spec.second, 0)
    }

    private fun ask(provider: ComponentName, widget: String, options: List<FnwOption>, index: Int) {
        if (index == options.size) {
            sendBroadcast(
                Intent(AppWidgetManager.ACTION_APPWIDGET_UPDATE)
                    .setComponent(provider)
                    .putExtra(AppWidgetManager.EXTRA_APPWIDGET_IDS, intArrayOf(widgetId)),
            )
            setResult(RESULT_OK, Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID, widgetId))
            finish()
            return
        }
        val option = options[index]
        val prefs = Fnw.prefs(this)
        val key = "fnw.$widget.@$widgetId.${option.key}"
        val current = prefs.all[key]?.toString() ?: option.initial
        val night = (resources.configuration.uiMode and Configuration.UI_MODE_NIGHT_MASK) ==
            Configuration.UI_MODE_NIGHT_YES
        val theme = if (night) {
            android.R.style.Theme_DeviceDefault_Dialog_Alert
        } else {
            android.R.style.Theme_DeviceDefault_Light_Dialog_Alert
        }
        AlertDialog.Builder(this, theme)
            .setTitle(option.label)
            .setSingleChoiceItems(option.choices, option.choices.indexOf(current)) { dialog, which ->
                prefs.edit().putString(key, option.choices[which]).commit()
                dialog.dismiss()
                ask(provider, widget, options, index + 1)
            }
            .setOnCancelListener { finish() }
            .show()
    }
}

class DashboardWidgetProvider : HomeWidgetProvider() {
    override fun onUpdate(
        context: Context,
        appWidgetManager: AppWidgetManager,
        appWidgetIds: IntArray,
        widgetData: SharedPreferences,
    ) {
        val d = FnwData(widgetData, NAME, INITIAL, options = OPTIONS)
        for (id in appWidgetIds) {
            appWidgetManager.updateAppWidget(id, views(context, d.forWidget(id), appWidgetManager.getAppWidgetOptions(id)))
        }
        Fnw.schedule(context, javaClass, nextRefresh(context, d))
    }

    override fun onAppWidgetOptionsChanged(
        context: Context,
        appWidgetManager: AppWidgetManager,
        appWidgetId: Int,
        newOptions: Bundle,
    ) {
        val d = FnwData(Fnw.prefs(context), NAME, INITIAL, id = appWidgetId, options = OPTIONS)
        appWidgetManager.updateAppWidget(appWidgetId, views(context, d, newOptions))
    }

    override fun onReceive(context: Context, intent: Intent) {
        if (Fnw.applyAction(context, intent, NAME, INITIAL) || Fnw.applyItem(context, intent, NAME, INITIAL) || Fnw.isRefresh(intent)) {
            val manager = AppWidgetManager.getInstance(context)
            val ids = manager.getAppWidgetIds(ComponentName(context, javaClass))
            onUpdate(context, manager, ids, Fnw.prefs(context))
            return
        }
        super.onReceive(context, intent)
    }

    private fun nextRefresh(context: Context, d: FnwData): Long? = listOfNotNull(
        d.nextChange,
        d.date("due")?.takeIf { it > d.now },
    ).minOrNull()

    private fun views(context: Context, d: FnwData, options: Bundle?): RemoteViews {
        return main(context, d)
    }

    private fun main(context: Context, d: FnwData): RemoteViews {
        val v = RemoteViews(context.packageName, R.layout.fnw_dashboard_main)
        v.setTextViewText(R.id.fnw_v0, d.resolve("Count {count}"))
        v.setTextViewText(R.id.fnw_v1, Fnw.spans(context, listOf(FnwSpan(d.resolve("{count}"), 24f, true, false, null, R.color.fnw_c1), FnwSpan(d.resolve(" items"), 14f, false, false, null, R.color.fnw_c2))))
        Fnw.progress(v, R.id.fnw_v2, d.number("progress"), 1.0)
        Fnw.progress(v, R.id.fnw_v3, d.number("progress"), 1.0)
        Fnw.image(v, R.id.fnw_v4, d.value("photo"))
        val c0 = d.check("isTrue", "on", null)
        v.setViewVisibility(R.id.fnw_v5, if (c0) View.VISIBLE else View.GONE)
        Fnw.timer(v, R.id.fnw_v6, d.date("due"))
        v.setViewVisibility(R.id.fnw_v7, if (!c0) View.VISIBLE else View.GONE)
        v.setTextViewText(R.id.fnw_v8, Fnw.formatDate(d.date("due"), "d MMM"))
        v.setOnClickPendingIntent(R.id.fnw_v9, Fnw.native(context, javaClass, "fnw://action?homeWidget&w=Dashboard&op=inc&k=count&by=1&max=9"))
        v.setOnClickPendingIntent(R.id.fnw_v12, Fnw.native(context, javaClass, "fnw://action?homeWidget&w=Dashboard&op=toggle&k=on"))
        v.setTextViewText(R.id.fnw_v13, d.resolve("{title0}"))
        v.setOnClickPendingIntent(R.id.fnw_v14, Fnw.native(context, javaClass, "fnw://action?homeWidget&w=Dashboard&op=toggle&k=on"))
        v.setTextViewText(R.id.fnw_v15, d.resolve("{title1}"))
        v.setOnClickPendingIntent(R.id.fnw_v16, Fnw.native(context, javaClass, "fnw://action?homeWidget&w=Dashboard&op=toggle&k=on"))
        v.setTextViewText(R.id.fnw_v17, d.resolve("{title2}"))
        if (Build.VERSION.SDK_INT >= 31) {
            v.setViewVisibility(R.id.fnw_v10, View.VISIBLE)
            v.setViewVisibility(R.id.fnw_v11, View.GONE)
            val items = RemoteViews.RemoteCollectionItems.Builder()
            for (i in 0 until 3) items.addItem(i.toLong(), mainList0(context, d.at(i)))
            v.setRemoteAdapter(R.id.fnw_v10, items.setViewTypeCount(1).build())
            v.setPendingIntentTemplate(R.id.fnw_v10, Fnw.itemTemplate(context, javaClass))
        }
        v.setOnClickPendingIntent(android.R.id.background, Fnw.open(context, "fnw://open?homeWidget&w=Dashboard"))
        return v
    }

    private fun mainList0(context: Context, d: FnwData): RemoteViews {
        val v = RemoteViews(context.packageName, R.layout.fnw_dashboard_main_list0)
        v.setOnClickFillInIntent(R.id.fnw_v0, Fnw.fillIn("fnw://action?homeWidget&w=Dashboard&op=toggle&k=on".replace("%23", d.index.toString())))
        v.setTextViewText(R.id.fnw_v1, d.resolve("{title#}"))
        return v
    }

    companion object {
        const val NAME = "Dashboard"
        val OPTIONS = listOf<String>()
        val INITIAL = mapOf<String, String>(
            "count" to "0",
            "progress" to "0.4",
            "on" to "false",
            "due" to "",
            "photo" to "",
            "title0" to "",
            "title1" to "",
            "title2" to "",
        )
    }
}

